## Conseils d''utilisation
L''huile essentielle de Menthe Poivrée peut être utilisée en inhalation, en diffusion ou en application cutanée après dilution dans une huile végétale adaptée. En raison de sa forte concentration en menthol, elle doit toujours être utilisée avec modération et dans le respect des doses recommandées.

## Précautions d''emploi
- Toujours diluer avant toute application cutanée.
- Effectuer un test cutané avant la première utilisation.
- Ne pas appliquer sur le visage des nourrissons ou des jeunes enfants.
- Déconseillée chez les enfants de moins de 6 ans, chez la femme enceinte ou allaitante sans avis d''un professionnel de santé.
- Déconseillée aux personnes souffrant d''épilepsie ou ayant des antécédents de convulsions sans avis médical.
- Éviter chez les personnes présentant certaines pathologies cardiaques ou un déficit en G6PD sans avis d''un professionnel de santé.
