## 🌍 Le saviez-vous ?
La Menthe Poivrée est un hybride naturel issu de la Menthe aquatique (Mentha aquatica) et de la Menthe verte (Mentha spicata). Son exceptionnelle richesse en menthol lui confère son effet rafraîchissant caractéristique, très recherché aussi bien en aromathérapie qu''en pharmacie, en cosmétique, en confiserie et dans les produits d''hygiène bucco-dentaire.

