La Myrrhe est l''une des plus anciennes substances aromatiques connues de l''humanité. Utilisée depuis plus de 5 000 ans en Afrique et au Moyen-Orient, elle était considérée comme aussi précieuse que l''or. Elle figure parmi les célèbres présents offerts à l''Enfant Jésus par les Rois Mages, aux côtés de l''encens et de l''or. Aujourd''hui encore, son huile essentielle demeure très recherchée pour son parfum exceptionnel, ses usages traditionnels et sa grande valeur en aromathérapie.

