Le Myrte est un arbuste emblématique du bassin méditerranéen. Depuis l''Antiquité, il symbolise la pureté, la paix et la longévité. Les Grecs et les Romains lui attribuaient une place de choix dans leurs traditions, utilisant ses feuilles parfumées lors des cérémonies et pour parfumer les habitations. Aujourd''hui encore, son huile essentielle est recherchée pour sa douceur aromatique et sa remarquable polyvalence.

