L''huile essentielle de Ravintsara Bio peut être utilisée en diffusion atmosphérique, en inhalation ou en application cutanée après dilution dans une huile végétale adaptée. Elle est particulièrement appréciée dans les huiles de massage destinées au confort respiratoire et au soutien de la vitalité. Respectez toujours les doses recommandées.

