## 🌍 Le saviez-vous ?
Le mot « Ravintsara » signifie « feuille bonne à tout » en malgache. Bien que le Ravintsara appartienne à la même espèce botanique que le Camphrier (Cinnamomum camphora), les conditions climatiques uniques de Madagascar lui confèrent une composition aromatique très différente, dominée par le 1,8-cinéole. Cette particularité explique pourquoi il est aujourd''hui considéré comme l''une des huiles essentielles les plus emblématiques de l''aromathérapie moderne.

