- Pour les soins capillaires, associez-la à l''huile végétale de Jojoba ou de Coco afin d''obtenir des cheveux brillants, souples et nourris.

## Conseils d''utilisation
L''huile essentielle d''Ylang-Ylang Bio peut être utilisée en diffusion atmosphérique, en application cutanée après dilution dans une huile végétale adaptée ou dans des préparations cosmétiques naturelles. Elle est particulièrement appréciée dans les soins des cheveux, les huiles de massage et les synergies relaxantes. Respectez toujours les doses recommandées.

## Précautions d''emploi
- Toujours diluer avant toute application cutanée.
- Effectuer un test cutané avant la première utilisation.
- Son parfum très puissant peut provoquer une sensation d''inconfort ou des maux de tête chez certaines personnes en cas de diffusion prolongée ; utiliser avec modération.
- Déconseillée pendant les trois premiers mois de grossesse sans avis d''un professionnel de santé.
- Demander l''avis d''un professionnel avant toute utilisation chez les jeunes enfants.
- Éviter le contact avec les yeux et les muqueuses.
- Conserver à l''abri de la chaleur, de la lumière et hors de portée des enfants.

## 🌍 Le saviez-vous ?
Le nom « Ylang-Ylang » signifie « fleur des fleurs » dans certaines langues des Philippines, berceau historique de cet arbre tropical. À Madagascar, où il est aujourd''hui largement cultivé, ses fleurs sont récoltées à la main à l''aube afin de préserver toute leur richesse aromatique. Son huile essentielle est une matière première incontournable de la haute parfumerie et entre dans la composition de nombreux parfums emblématiques.

