Appliquer en bain d''huile avant le shampooing ou en mélange avec une huile végétale plus fluide.

#### En soin du cuir chevelu
Masser délicatement le cuir chevelu, laisser agir puis procéder au shampooing.

#### Pour la barbe, les cils et les sourcils
Appliquer une très faible quantité à l''aide d''une brosse propre, en évitant tout contact avec les yeux.

#### En aromathérapie
Peut être utilisée comme support, seule ou en mélange avec d''autres huiles végétales PUR''ESSENCE, pour certaines préparations destinées aux soins cutanés et capillaires.

