## 🧬 Pourquoi cette formulation ?
Cette synergie associe trois huiles essentielles aux mécanismes d''action complémentaires. L''Arbre à Thé constitue la base purifiante de la formule grâce à sa richesse en terpinène-4-ol.
Le Manuka renforce l''action assainissante tout en apportant un effet apaisant particulièrement intéressant pour les peaux réactives.
La Lavande Vraie complète la synergie en favorisant le confort cutané et le renouvellement physiologique de la peau. Ensemble, ces huiles essentielles offrent une approche globale des peaux à tendance acnéique.

