## 🍎 Conseils nutritionnels & hygiène de vie
- Privilégier une alimentation riche en légumes, fruits et aliments peu transformés.
- Limiter les boissons sucrées et les produits à index glycémique élevé.
- Veiller à un apport suffisant en zinc et en oméga-3 dans le cadre d''une alimentation équilibrée.
- Nettoyer la peau avec un soin doux, non agressif.
- Éviter de manipuler ou de percer les boutons.
- Dormir suffisamment et apprendre à mieux gérer le stress.

## Précautions d''emploi
- Usage externe uniquement.
- Toujours diluer avant application cutanée.
- Effectuer un test cutané avant la première utilisation.
- Éviter le contact avec les yeux et les muqueuses.
- Déconseillée chez la femme enceinte ou allaitante sans avis d''un professionnel de santé.
- Tenir hors de portée des enfants.

