## 🍎 Conseils nutritionnels & hygiène de vie
- Manger lentement et bien mastiquer les aliments.
- Fractionner les repas si nécessaire.
- Limiter les boissons gazeuses et les aliments très fermentescibles lorsqu''ils sont mal tolérés.
- Privilégier une alimentation riche en fibres, en adaptant progressivement les quantités selon la tolérance digestive.
- Boire suffisamment d''eau tout au long de la journée.
- Pratiquer une activité physique régulière afin de favoriser le transit intestinal.

## Précautions d''emploi
- Respecter les doses recommandées.
- La Menthe Poivrée est déconseillée chez le jeune enfant et doit être utilisée avec prudence chez les personnes présentant certaines pathologies neurologiques ou des antécédents de convulsions.
- Le Fenouil Doux est déconseillé chez les personnes présentant ou ayant présenté un cancer hormono-dépendant, sauf avis d''un professionnel de santé.
- Déconseillée chez la femme enceinte ou allaitante sans avis d''un professionnel de santé.
- Toujours diluer avant une application cutanée.
- Effectuer un test cutané avant la première utilisation.
- Tenir hors de portée des enfants.

