## 🍎 Conseils nutritionnels & hygiène de vie
- Veiller à des apports suffisants en vitamines du groupe B, notamment B1, B6 et B12.
- Consommer des aliments riches en magnésium et en oméga-3.
- Maintenir un bon équilibre glycémique.
- Pratiquer une activité physique régulière et adaptée.
- Éviter le tabac et limiter la consommation d''alcool.
- Dormir suffisamment afin de favoriser les mécanismes naturels de récupération.

## Précautions d''emploi
- Respecter les doses recommandées.
- La Menthe Poivrée est déconseillée chez le jeune enfant.
- Éviter toute application sur le visage, à proximité des yeux et des muqueuses.
- Utiliser avec prudence chez les personnes ayant des antécédents de convulsions ou d''épilepsie.
- Déconseillée chez la femme enceinte ou allaitante sans avis d''un professionnel de santé.
- Effectuer un test cutané avant la première utilisation.
- Tenir hors de portée des enfants.
- En cas de perte de sensibilité importante, de faiblesse musculaire progressive ou de douleurs persistantes, consulter un professionnel de santé.

