## 🍎 Conseils nutritionnels & hygiène de vie
- Boire 1,5 à 2 litres d''eau par jour, sauf contre-indication médicale.
- Ne pas retenir les envies d''uriner.
- Adopter une hygiène intime douce, sans excès de produits irritants.
- Porter des sous-vêtements en fibres naturelles lorsque cela est possible.
- Limiter les sucres ajoutés et les aliments ultra-transformés.
- Maintenir une alimentation riche en fruits, légumes et fibres.

## Précautions d''emploi
- Respecter strictement les doses recommandées.
- Les huiles essentielles d''Origan et de Sarriette des Montagnes sont très puissantes, riches en phénols et dermocaustiques. Elles doivent toujours être fortement diluées avant toute application cutanée.
- Déconseillée chez la femme enceinte ou allaitante et chez le jeune enfant.
- Ne pas appliquer sur les muqueuses.
- Effectuer un test cutané avant la première utilisation.
- Tenir hors de portée des enfants.
- En cas de brûlures urinaires importantes, de fièvre, de douleurs lombaires, de sang dans les urines, d''écoulement génital ou de suspicion d''infection sexuellement transmissible, consulter rapidement un professionnel de santé.

