Diffuser pendant 15 à 20 minutes dans la chambre avant le coucher, puis arrêter la diffusion avant de dormir.

### 🌿 Inhalation
Déposer quelques gouttes sur un mouchoir ou un diffuseur personnel et respirer profondément avant le coucher.

