L''Hydrolat d''Hamamélis Bio s''utilise pur en vaporisation ou à l''aide d''un coton sur le visage, le cou, les jambes ou toute autre zone souhaitée. Il peut être intégré à une routine cosmétique quotidienne ou servir de base à des préparations naturelles.

## Précautions d''emploi
- Usage externe principalement.
- Éviter le contact direct avec les yeux.
- Conserver au réfrigérateur après ouverture.
- Utiliser de préférence dans les trois mois suivant l''ouverture.
- Tenir hors de portée des jeunes enfants.

## 🌍 Le saviez-vous ?
Originaire d''Amérique du Nord, l''Hamamélis est surnommé « l''arbuste aux sorcières » (Witch Hazel) en raison de son histoire dans les traditions amérindiennes. Depuis plusieurs siècles, il est apprécié pour ses qualités cosmétiques et son utilisation dans les soins de la peau.

